205	@Slf4j
206	@Configuration
207	@RequiredArgsConstructor
208	public class UpdateShipmentStatusesJobConfig {
209	
210	    private final JobRepository jobRepository;
211	    private final PlatformTransactionManager transactionManager;
212	    private final EntityManagerFactory entityManagerFactory;
213	
214	    private final OrderShipmentRepository orderShipmentRepository;
215	    private final NotificationCommandService notificationService;
216	    private final OrderShipmentCommandService orderService;
217	    private final CjTrackingPlaywright cjTrackingPlaywright;
218	
219	    private static final int CHUNK_SIZE = 50;
220	    private static final int SKIP_LIMIT = 50;
221	
222	    @Bean
223	    public Job updateShipmentStatusesJob() {
224	        log.info("배송 상태 업데이트 작업 구성");
225	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
226	                .start(updateShipmentStatusesStep())
227	                .build();
228	    }
229	
230	    @Bean
231	    public Step updateShipmentStatusesStep() {
232	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
233	
234	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
235	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
236	                .reader(shipmentItemReader())
237	                .processor(new ShipmentItemProcessor(
238	                        playwrightBrowserManager(), // Bean or new
239	                        notificationService,
240	                        orderService
241	                ))
242	                .writer(shipmentJpaItemWriter())
243	                .faultTolerant()
244	                .skip(Exception.class)
245	                .skipLimit(SKIP_LIMIT)
246	                .listener(shipmentSkipListener())
247	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
248	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
249	                .build();
250	    }
