481	/**
482	 * 배송 상태 배치 처리를 위한 ItemProcessor
483	 * 주문 배송 상태를 조회하고 처리합니다.
484	 */
485	@Slf4j
486	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
487	
488	    private final PlaywrightBrowserManager browserManager;
489	    private final NotificationCommandService notificationService;
490	    private final OrderShipmentCommandService orderService;
491	
492	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
493	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
494	    private static final int TIMEOUT_MS = 30000; // 30초
495	
496	    /**
497	     * 배송 상태 처리기 생성자
498	     *
499	     * @param browserManager Playwright 브라우저 관리자
500	     * @param notificationService 알림 서비스
501	     * @param orderService 주문 서비스
502	     */
503	    public ShipmentItemProcessor(
504	            PlaywrightBrowserManager browserManager,
505	            NotificationCommandService notificationService,
506	            OrderShipmentCommandService orderService
507	    ) {
508	        this.browserManager = browserManager;
509	        this.notificationService = notificationService;
510	        this.orderService = orderService;
511	    }
512	
513	    /**
514	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
515	     *
516	     * @param orderShipment 처리할 배송 정보
517	     * @return 업데이트된 배송 정보
518	     * @throws Exception 처리 중 오류 발생 시
519	     */
520	    @Override
521	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
522	        String trackingNumber = orderShipment.getTrackingNumber();
523	        Long shipmentId = orderShipment.getId();
524	
525	        if (trackingNumber == null || trackingNumber.isBlank()) {
526	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
527	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
528	        }
529	
530	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
531	                shipmentId, trackingNumber, orderShipment.getStatus());
532	
533	        Page page = null;
534	        try {
535	            // browserManager를 통해 페이지 생성
536	            page = browserManager.newPage();
537	            if (page == null) {
538	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
539	            }
540	
541	            // 타임아웃 설정
542	            page.setDefaultTimeout(TIMEOUT_MS);
543	
544	            // 배송 추적 URL로 이동
545	            String url = TRACKING_URL_PREFIX + trackingNumber;
546	            log.debug("배송 조회 페이지로 이동: {}", url);
547	            page.navigate(url);
548	
549	            // 배송 상태 테이블 로드 대기
550	            log.debug("배송 상태 테이블 로드 대기");
551	            page.waitForSelector(STATUS_SELECTOR);
552	
553	            // 최종 HTML 가져오기
554	            String renderedHtml = page.content();
555	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
556	
557	            // HTML 파싱하여 배송 상태 추출
558	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
559	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
560	
561	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
562	                    shipmentId, statusText, newStatus);
563	
564	            // 현재 상태와 동일한 경우 중복 처리 방지
565	            if (orderShipment.getStatus() == newStatus) {
566	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
567	                        shipmentId, newStatus);
568	                return orderShipment;
569	            }
570	
571	            // 상태에 따른 처리
572	            if (newStatus == ShipmentStatus.DELIVERED) {
573	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
574	                        shipmentId, orderShipment.getOrder().getId());
575	
576	                // 배송 상태 업데이트
577	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
578	
579	                // 주문 완료 처리 및 알림
580	                orderService.completeOrder(orderShipment.getOrder().getId());
581	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
582	
583	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
584	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
585	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
586	
587	            } else {
588	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
589	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
590	            }
591	
592	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
593	                    shipmentId, orderShipment.getStatus());
594	
595	            return orderShipment;
596	
597	        } catch (Exception e) {
598	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
599	                    shipmentId, trackingNumber, e.getMessage(), e);
600	
601	            // ShipmentException 타입이 아닌 경우 래핑
602	            if (!(e instanceof ShipmentException)) {
603	                throw new ShipmentException(
604	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
605	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
606	                        e
607	                );
608	            }
609	            throw e;
610	        } finally {
611	            // 페이지 리소스 해제
612	            if (page != null) {
613	                try {
614	                    page.close();
615	                    log.debug("페이지 리소스 해제 완료");
616	                } catch (Exception e) {
617	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
618	                }
619	            }
620	        }
621	    }
622	
623	    /**
624	     * HTML에서 배송 상태를 파싱합니다.
625	     *
626	     * @param html 파싱할 HTML 문자열
627	     * @param trackingNumber 로깅용 운송장 번호
628	     * @return 배송 상태 문자열
629	     * @throws ShipmentException 파싱 실패 시 발생
630	     */
631	    private String parseStatusFromHtml(String html, String trackingNumber) {
632	        try {
633	            Document doc = Jsoup.parse(html);
634	            Elements rows = doc.select(STATUS_SELECTOR);
635	
636	            if (rows.isEmpty()) {
637	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
638	                throw new ShipmentException(
639	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
640	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
641	                );
642	            }
643	
644	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
645	            String statusText = rows.last().select("td").get(4).text().trim();
646	
647	            if (statusText.isEmpty()) {
648	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
649	                throw new ShipmentException(
650	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
651	                        "배송 상태 정보를 찾을 수 없습니다."
652	                );
653	            }
654	
655	            return statusText;
656	
657	        } catch (IndexOutOfBoundsException e) {
658	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
659	            throw new ShipmentException(
660	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
661	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
662	                    e
663	            );
664	        } catch (Exception e) {
665	            if (e instanceof ShipmentException) {
666	                throw (ShipmentException) e;
667	            }
668	
669	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
670	            throw new ShipmentException(
671	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
672	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
673	                    e
674	            );
675	        }
676	    }
