205	@Slf4j
206	@Configuration
207	@RequiredArgsConstructor
208	public class UpdateShipmentStatusesJobConfig {
209	
210	    private final JobRepository jobRepository;
211	    private final PlatformTransactionManager transactionManager;
212	    private final EntityManagerFactory entityManagerFactory;
213	
214	    private final OrderShipmentRepository orderShipmentRepository;
215	    private final NotificationCommandService notificationService;
216	    private final OrderShipmentCommandService orderService;
217	    private final CjTrackingPlaywright cjTrackingPlaywright;
