230	    @Bean
231	    public Step updateShipmentStatusesStep() {
232	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
233	
234	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
235	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
236	                .reader(shipmentItemReader())
237	                .processor(new ShipmentItemProcessor(
238	                        playwrightBrowserManager(), // Bean or new
239	                        notificationService,
240	                        orderService
241	                ))
242	                .writer(shipmentJpaItemWriter())
243	                .faultTolerant()
244	                .skip(Exception.class)
245	                .skipLimit(SKIP_LIMIT)
246	                .listener(shipmentSkipListener())
247	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
248	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
249	                .build();
250	    }
