267	    /**
268	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
269	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
270	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
271	     */
272	    @Bean
273	    @StepScope
274	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
275	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
276	
277	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
278	        return orderShipment -> {
279	            String trackingNumber = orderShipment.getTrackingNumber();
280	            Long shipmentId = orderShipment.getId();
281	
282	            if (trackingNumber == null || trackingNumber.isBlank()) {
283	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
284	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
285	            }
286	
287	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
288	                    shipmentId, trackingNumber, orderShipment.getStatus());
289	
290	            try {
291	                // 2-1) 현재 상태 가져오기
292	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
293	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
294	
295	                // 2-2) 매핑
296	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
297	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
298	
299	                // 현재 상태와 동일한 경우 중복 처리 방지
300	                if (orderShipment.getStatus() == newStatus) {
301	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
302	                            shipmentId, newStatus);
303	                    return orderShipment;
304	                }
305	
306	                // 2-3) 상태에 따른 처리
307	                if (newStatus == ShipmentStatus.DELIVERED) {
308	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
309	                            shipmentId, orderShipment.getOrder().getId());
310	
311	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
312	                    // Order 상태도 COMPLETED 로 변경
313	                    orderService.completeOrder(orderShipment.getOrder().getId());
314	                    // 알림 발송
315	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
316	                }
317	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
318	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
319	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
320	                    // 필요시 알림, 로직 추가
321	                }
322	                else {
323	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
324	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
325	                }
326	
327	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
328	                return orderShipment; // Writer로 넘김
329	
330	            } catch (Exception e) {
331	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
332	                        shipmentId, trackingNumber, e.getMessage(), e);
333	
334	                // ShipmentException 타입이 아닌 경우 래핑
335	                if (!(e instanceof ShipmentException)) {
336	                    throw new ShipmentException(
337	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
338	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
339	                            e
340	                    );
341	                }
342	                throw e;
343	            }
344	        };
345	    }
