347	    /**
348	     * CJ대한통운 배송 상태 조회를 위한 메서드
349	     *
350	     * @param trackingNumber 운송장 번호
351	     * @return 배송 상태 텍스트
352	     * @throws Exception 조회 실패 시 발생
353	     */
354	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
355	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
356	
357	        try {
358	            // 예시: 로직 단순화
359	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
360	            Document doc = Jsoup.connect(url).get();
361	            // tbody#statusDetail 의 마지막 tr => 5번째 td
362	            Elements rows = doc.select("tbody#statusDetail tr");
363	            if (rows.isEmpty()) {
364	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
365	                throw new ShipmentException(
366	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
367	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
368	                );
369	            }
370	
371	            String status = rows.last().select("td").get(4).text();
372	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
373	            return status;
374	
375	        } catch (Exception e) {
376	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
377	
378	            if (e instanceof ShipmentException) {
379	                throw e;
380	            }
381	
382	            throw new ShipmentException(
383	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
384	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
385	                    e
386	            );
387	        }
388	    }
