623	    /**
624	     * HTML에서 배송 상태를 파싱합니다.
625	     *
626	     * @param html 파싱할 HTML 문자열
627	     * @param trackingNumber 로깅용 운송장 번호
628	     * @return 배송 상태 문자열
629	     * @throws ShipmentException 파싱 실패 시 발생
630	     */
631	    private String parseStatusFromHtml(String html, String trackingNumber) {
632	        try {
633	            Document doc = Jsoup.parse(html);
634	            Elements rows = doc.select(STATUS_SELECTOR);
635	
636	            if (rows.isEmpty()) {
637	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
638	                throw new ShipmentException(
639	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
640	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
641	                );
642	            }
643	
644	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
645	            String statusText = rows.last().select("td").get(4).text().trim();
646	
647	            if (statusText.isEmpty()) {
648	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
649	                throw new ShipmentException(
650	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
651	                        "배송 상태 정보를 찾을 수 없습니다."
652	                );
653	            }
654	
655	            return statusText;
656	
657	        } catch (IndexOutOfBoundsException e) {
658	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
659	            throw new ShipmentException(
660	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
661	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
662	                    e
663	            );
664	        } catch (Exception e) {
665	            if (e instanceof ShipmentException) {
666	                throw (ShipmentException) e;
667	            }
668	
669	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
670	            throw new ShipmentException(
671	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
672	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
673	                    e
674	            );
675	        }
676	    }
