 30	/**
 31	 * 주문 배송 관련 비즈니스 로직을 처리하는 서비스
 32	 */
 33	@Slf4j
 34	@Service
 35	@RequiredArgsConstructor
 36	public class OrderShipmentCommandService {
 37	
 38	    private final OrderShipmentRepository orderShipmentRepository;
 39	    private final NotificationCommandService notificationCommandService;
 40	    private final SaleBidQueryService saleBidQueryService;
 41	    private final OrderBidQueryService orderBidQueryService;
 42	    private final WarehouseStorageCommandService warehouseStorageCommandService;
 43	    private final CjTrackingPlaywright cjTrackingPlaywright;
 44	
 45	    /**
 46	     * 주문에 대한 배송 정보를 생성합니다.
 47	     *
 48	     * @param order 주문 엔티티
 49	     * @param receiverName 수령인 이름
 50	     * @param receiverPhone 수령인 전화번호
 51	     * @param postalCode 우편번호
 52	     * @param address 배송지 주소
 53	     * @return 생성된 배송 정보
 54	     */
 55	    @Transactional
 56	    public OrderShipment createOrderShipment(Order order, String receiverName, String receiverPhone,
 57	                                             String postalCode, String address) {
 58	        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
 59	                order.getId(), receiverName);
 60	
 61	        OrderShipment shipment = OrderShipment.builder()
 62	                .order(order)
 63	                .receiverName(receiverName)
 64	                .receiverPhone(receiverPhone)
 65	                .postalCode(postalCode)
 66	                .address(address)
 67	                .status(ShipmentStatus.PENDING) // 초기 상태 설정
 68	                .build();
 69	
 70	        OrderShipment savedShipment = orderShipmentRepository.save(shipment);
 71	        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
 72	                savedShipment.getId(), order.getId());
 73	
 74	        return savedShipment;
 75	    }
 76	
 77	    /**
 78	     * 배송 상태를 업데이트합니다.
 79	     *
 80	     * @param shipment 업데이트할 배송 엔티티
 81	     * @param newStatus 새로운 배송 상태
 82	     */
 83	    @Transactional
 84	    public void updateShipmentStatus(OrderShipment shipment, ShipmentStatus newStatus) {
 85	        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
 86	                shipment.getId(), shipment.getStatus(), newStatus);
 87	
 88	        try {
 89	            shipment.updateStatus(newStatus);
 90	            orderShipmentRepository.save(shipment);
 91	
 92	            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
 93	                    shipment.getId(), newStatus);
 94	        } catch (IllegalStateException e) {
 95	            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
 96	                    shipment.getId(), e.getMessage(), e);
 97	
 98	            throw new ShipmentException(
 99	                    ShipmentErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
100	                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
101	                    e
102	            );
103	        }
104	    }
105	
106	    /**
107	     * 주문 완료에 따라 판매 상태를 'SOLD'로 변경합니다.
108	     *
109	     * @param orderId 주문 ID
110	     */
111	    @Transactional
112	    public void updateSaleStatusToSold(Long orderId) {
113	        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);
114	
115	        // SaleBid 조회
116	        SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
117	        if (saleBid != null) {
118	            Sale sale = saleBid.getSale();
119	            if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
120	                log.info("Sale 상태 'SOLD'로 변경: saleId={}, sellerId={}",
121	                        sale.getId(), sale.getSeller().getId());
122	
123	                sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
124	
125	                // 창고 상태 업데이트
126	                if (sale.isWarehouseStorage()) {
127	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
128	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
129	                }
130	
131	                // 판매자에게 알림 생성
132	                User seller = sale.getSeller();
133	                notificationCommandService.createNotification(
134	                        seller.getId(),
135	                        NotificationCategory.SHOPPING,
136	                        NotificationType.BID,
137	                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
138	                );
139	
140	                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
141	                        seller.getId(), sale.getId());
142	            } else {
143	                log.debug("Sale 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
144	            }
145	        } else {
146	            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
147	        }
148	
149	        // OrderBid 조회
150	        try {
151	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
152	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
153	
154	            if (orderBid != null) {
155	                Sale sale = orderBid.getSale();
156	                if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
157	                    log.info("OrderBid 기반 Sale 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
158	                            orderBid.getId(), sale.getId());
159	
160	                    sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
161	
162	                    // 판매자에게 알림 생성
163	                    User seller = sale.getSeller();
164	                    notificationCommandService.createNotification(
165	                            seller.getId(),
166	                            NotificationCategory.SHOPPING,
167	                            NotificationType.BID,
168	                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
169	                    );
170	
171	                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
172	                            seller.getId(), sale.getId());
173	                } else {
174	                    log.debug("Sale 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
175	                }
176	            }
177	        } catch (IllegalArgumentException e) {
178	            log.warn("OrderBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());
179	            // OrderBid가 없는 경우 예외로 중단하지 않고 진행
180	        }
181	
182	        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
183	    }
184	
185	    /**
186	     * 주문을 완료 상태로 변경하고 관련된 후속 작업을 처리합니다.
187	     *
188	     * @param orderId 완료할 주문 ID
189	     */
190	    @Transactional
191	    public void completeOrder(Long orderId) {
192	        log.info("주문 완료 처리 시작: orderId={}", orderId);
193	
194	        try {
195	            // OrderBid 조회
196	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
197	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
198	
199	            Order order = orderBid.getOrder();
200	            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
201	                    order.getId(), order.getUser().getId(), order.getStatus());
202	
203	            // 주문 상태를 COMPLETED로 변경
204	            order.updateStatus(OrderStatus.COMPLETED);
205	            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);
206	
207	            // 판매 상태 변경 로직
208	            updateSaleStatusToSold(orderId);
209	
210	            // 주문 완료 알림
211	            User buyer = order.getUser();
212	            notificationCommandService.createNotification(
213	                    buyer.getId(),
214	                    NotificationCategory.SHOPPING,
215	                    NotificationType.BID,
216	                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
217	            );
218	
219	            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
220	
221	        } catch (Exception e) {
222	            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
223	            throw new ShipmentException(
224	                    ShipmentErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
225	                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
226	                    e
227	            );
228	        }
229	    }
230	
231	    /**
232	     * 배송 정보에 운송장 정보를 업데이트하고 관련 상태를 변경합니다.
233	     *
234	     * @param shipmentId 배송 ID
235	     * @param courier 택배사 이름
236	     * @param trackingNumber 운송장 번호
237	     */
238	    @Transactional
239	    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
240	        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
